-- clotere-pro — migration 0030 : domaines expert-comptable inspirés de Dougs (services, clientèle, formes, secteurs).
-- Les domaines « profil » (clientèle, formes, secteurs) s'affichent sur la fiche mais ne donnent pas de motif.
-- Les ids de 0008 sont conservés ; « LMNP » passe de Particuliers à « SCI & LMNP ».

alter table domaines add column if not exists profil_seulement boolean not null default false;


-- Reprise des spécialités déplacées
update motifs set specialite_ids = array_replace(specialite_ids, 'comptable-particulier-lmnp', 'comptable-immobilier-lmnp') where 'comptable-particulier-lmnp' = any(specialite_ids);
update bookings set specialite_id = 'comptable-immobilier-lmnp' where specialite_id = 'comptable-particulier-lmnp';

-- Nettoyage des spécialités comptables qui n'existent plus
delete from specialites s using domaines d where s.domaine_id = d.id and d.profession = 'comptable' and s.id not in ('comptable-bilan-bilan-annuel', 'comptable-bilan-facturation-electronique', 'comptable-bilan-liasse', 'comptable-bilan-outils', 'comptable-bilan-tenue', 'comptable-changement-lettre-mission', 'comptable-changement-rattrapage', 'comptable-changement-reprise', 'comptable-clientele-artisans', 'comptable-clientele-associations', 'comptable-clientele-commercants', 'comptable-clientele-e-commerce', 'comptable-clientele-freelances', 'comptable-clientele-liberales', 'comptable-clientele-micro', 'comptable-clientele-pme', 'comptable-clientele-start-up', 'comptable-clientele-tpe', 'comptable-creation-aides', 'comptable-creation-depot-capital', 'comptable-creation-holding', 'comptable-creation-immatriculation', 'comptable-creation-previsionnel', 'comptable-creation-sci', 'comptable-creation-statut', 'comptable-fiscalite-cfe', 'comptable-fiscalite-controle', 'comptable-fiscalite-is', 'comptable-fiscalite-optimisation', 'comptable-fiscalite-remuneration', 'comptable-fiscalite-tva', 'comptable-formes-ei', 'comptable-formes-eurl', 'comptable-formes-holding', 'comptable-formes-lmnp', 'comptable-formes-micro', 'comptable-formes-sarl', 'comptable-formes-sas', 'comptable-formes-sasu', 'comptable-formes-sci', 'comptable-gestion-budget', 'comptable-gestion-financement', 'comptable-gestion-rentabilite', 'comptable-gestion-tableaux-bord', 'comptable-gestion-tresorerie', 'comptable-immobilier-foncier', 'comptable-immobilier-lmnp', 'comptable-immobilier-plus-value', 'comptable-immobilier-sci', 'comptable-juridique-approbation', 'comptable-juridique-cession', 'comptable-juridique-dirigeant', 'comptable-juridique-dissolution', 'comptable-juridique-regime', 'comptable-juridique-siege', 'comptable-juridique-statuts', 'comptable-particulier-etranger', 'comptable-particulier-ifi', 'comptable-particulier-patrimoine', 'comptable-particulier-revenus', 'comptable-secteurs-architectes', 'comptable-secteurs-beaute', 'comptable-secteurs-btp', 'comptable-secteurs-commerce', 'comptable-secteurs-communication', 'comptable-secteurs-conseil', 'comptable-secteurs-createurs', 'comptable-secteurs-e-commerce', 'comptable-secteurs-franchise', 'comptable-secteurs-immobilier', 'comptable-secteurs-juridique', 'comptable-secteurs-restauration', 'comptable-secteurs-sante', 'comptable-secteurs-tech', 'comptable-secteurs-transport', 'comptable-social-absences', 'comptable-social-charges', 'comptable-social-depart', 'comptable-social-embauche', 'comptable-social-mutuelle', 'comptable-social-paie');

-- Sujets des motifs comptables encore vides
update motifs m set specialite_ids = coalesce(
  nullif((select array_agg(s.id order by s.ordre) from specialites s join pro_specialites ps on ps.specialite_id = s.id and ps.professional_id = m.professional_id where s.domaine_id = m.domaine_id), '{}'),
  (select array_agg(s.id order by s.ordre) from specialites s where s.domaine_id = m.domaine_id), '{}')
where m.domaine_id like 'comptable-%' and m.specialite_ids = '{}';

notify pgrst, 'reload schema';
